/* Workshop-manual layout shared by the index and every stop. Colours are tokens; the 3-D scene reads them too. */
:root {
  --bg: #eef1f3; --panel: #ffffff; --fg: #16202a; --muted: #5a6875; --rule: #d3dae0;
  --accent: #0a6e8a; --stage: #e3e8ec;
  --l1: #d9480f; --l2: #e8a317; --l3: #2b8a3e; --l4: #1c64c4; --l5: #8e44ad;
  --metal: #8a96a1; --warn: #c92a2a;
  --display: -apple-system, BlinkMacSystemFont, "SF Pro Display", "Helvetica Neue", Arial, sans-serif;
  --body: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  color-scheme: light;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --bg: #10161b; --panel: #172028; --fg: #e4eaef; --muted: #93a2ae; --rule: #2a3742;
    --accent: #4fb8d6; --stage: #0c1115;
    --l1: #ff7a45; --l2: #f5c242; --l3: #5cc46f; --l4: #5b9bf0; --l5: #b77fd6; --metal: #6f7c87; --warn: #ff6b6b;
    color-scheme: dark;
  }
}
