/* Museum-style layout shared by the index and every stop: black pages, white serif headlines, quiet grey sans text, square
   photos. One dark palette; colours are tokens and the 3-D scene reads them too (stage.isDark() follows color-scheme). */
:root {
  --bg: #000000; --panel: #141414; --fg: #ffffff; --muted: #a3a3a3; --rule: #333333; --edge: #767676;
  --accent: #008dfc; --stage: #111111;
  --l1: #ff7a45; --l2: #f5c242; --l3: #5cc46f; --l4: #5b9bf0; --l5: #b77fd6; --metal: #6f7c87; --warn: #ff6b6b;
  --display: ui-serif, Georgia, "Times New Roman", serif;
  --body: -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --gutter: clamp(16px, 4vw, 40px); --max: 1240px;
  color-scheme: dark;
}
[hidden] { display: none !important; }
* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body { margin: 0; background: var(--bg); color: var(--fg); font-family: var(--body); font-size: 16px; line-height: 1.6; -webkit-font-smoothing: antialiased; }
a { color: var(--fg); text-decoration-color: var(--edge); text-underline-offset: 3px; }
.wrap {
  max-width: var(--max); margin: 0 auto; display: grid; gap: 28px;
  padding: max(20px, env(safe-area-inset-top)) max(var(--gutter), env(safe-area-inset-right)) max(48px, env(safe-area-inset-bottom)) max(var(--gutter), env(safe-area-inset-left));
}
.eyebrow { font-size: 12px; letter-spacing: .14em; text-transform: uppercase; color: var(--muted); }
h1 { font-family: var(--display); font-weight: 400; font-size: clamp(34px, 5.4vw, 60px); line-height: 1.08; margin: 10px 0 14px; text-wrap: balance; letter-spacing: -.01em; }
h2 { font-family: var(--display); font-weight: 400; font-size: 24px; line-height: 1.2; margin: 0 0 12px; text-wrap: balance; }
.lede { max-width: 62ch; font-size: 17px; color: var(--muted); margin: 0; }
.crumbs, .pager { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 8px 16px; font-size: 13px; color: var(--muted); }
.crumbs { border-bottom: 1px solid var(--rule); letter-spacing: .04em; }
.crumbs a, .pager a { display: inline-flex; align-items: center; min-height: 44px; text-decoration: none; }
.crumbs a:hover, .pager a:hover { text-decoration: underline; }
.pager { border-top: 1px solid var(--rule); padding-top: 8px; }
.pager a { font-family: var(--display); font-size: 20px; }

/* Buttons: 44 px targets, no double-tap zoom. Selected = white on black, as on the museum's own pages. */
button { font: 500 14px var(--body); color: var(--fg); background: transparent; border: 1px solid var(--edge); border-radius: 2px; padding: 8px 14px; min-height: 44px; cursor: pointer; touch-action: manipulation; }
button[aria-pressed="true"] { background: var(--fg); border-color: var(--fg); color: var(--bg); }
button:focus-visible, input:focus-visible, a:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.toolbar { display: flex; flex-wrap: wrap; gap: 12px 28px; align-items: center; }
.seg-group { display: flex; align-items: center; flex-wrap: wrap; gap: 6px 10px; }
.seg { display: inline-flex; flex-wrap: wrap; border: 1px solid var(--edge); border-radius: 2px; overflow: hidden; }
.seg button { border: 0; border-radius: 0; }
.seg button + button { border-left: 1px solid var(--edge); }
.seg-label, .label { font-size: 11px; letter-spacing: .12em; text-transform: uppercase; color: var(--muted); }

/* Viewer: stage keeps the museum photo's aspect so the overlay lines up; in phone landscape its height is capped to the
   viewport (width follows) so the page can still be scrolled past the touch-locked stage. */
.viewer { display: grid; grid-template-columns: minmax(0, 1fr) 320px; gap: 16px; align-items: start; }
@media (max-width: 860px) { .viewer { grid-template-columns: minmax(0, 1fr); } }
.stage {
  --ar: 1.4944; position: relative; background: var(--stage);
  aspect-ratio: var(--aspect, 1200 / 803); width: min(100%, calc((100svh - 32px) * var(--ar))); justify-self: center;
  overflow: hidden; touch-action: none; -webkit-user-select: none; user-select: none;
}
.stage img, .stage canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.stage img { filter: brightness(.72) saturate(.85); }
.stage .hint { position: absolute; left: 12px; bottom: 10px; font-size: 11px; letter-spacing: .08em; text-transform: uppercase; color: var(--muted); pointer-events: none; }
.stage .credit { position: absolute; right: 8px; bottom: 6px; font-size: 10px; color: #f1f3f5; background: rgba(0,0,0,.55); padding: 2px 6px; }
.stage .credit a { color: inherit; }
.stage .fail { position: absolute; inset: 0; margin: 0; padding: 16px; }
.side { display: grid; gap: 12px; align-content: start; min-width: 0; }
.panel { background: var(--panel); padding: 16px; display: grid; gap: 12px; min-width: 0; }
.readouts { display: grid; grid-template-columns: repeat(2, 1fr); gap: 12px 8px; }
.readouts div { display: grid; gap: 1px; }
.readouts output { font: 300 22px/1.25 var(--body); font-variant-numeric: tabular-nums; }
.readouts small { font-size: 11px; color: var(--muted); }
.row { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
.slider { display: grid; gap: 4px; }
input[type=range] { width: 100%; min-height: 32px; accent-color: var(--accent); }
.trace svg, svg.diagram { width: 100%; height: auto; display: block; }
.trace text, svg.diagram text { font-family: var(--mono); font-size: 9px; fill: var(--muted); }
.key { display: flex; gap: 14px; flex-wrap: wrap; font-size: 12px; color: var(--muted); }
.key i { display: inline-block; width: 14px; height: 3px; vertical-align: middle; margin-right: 5px; }
.legend { list-style: none; margin: 0; padding: 0; display: grid; gap: 4px; font-size: 13px; }
.legend li { display: grid; grid-template-columns: 12px 1fr; gap: 10px; align-items: center; }
.legend .sw { width: 12px; height: 12px; }
.cyls { display: grid; grid-template-columns: repeat(var(--n, 4), minmax(0, 1fr)); gap: 6px; }
.cyl { border: 1px solid var(--rule); padding: 6px 2px; display: grid; gap: 2px; text-align: center; min-width: 0; }
.cyl b { font-family: var(--mono); font-size: 11px; color: var(--muted); font-weight: 500; }
.cyl span { font-size: 11.5px; font-weight: 600; hyphens: auto; overflow-wrap: break-word; }
.cyl.power { border-color: var(--l1); box-shadow: inset 0 -3px 0 var(--l1); }
.badge { display: inline-block; font-size: 11px; padding: 2px 8px; border: 1px solid var(--edge); color: var(--muted); letter-spacing: .04em; }
.badge.on { background: var(--l1); border-color: var(--l1); color: var(--bg); }
.meter { height: 6px; background: var(--rule); overflow: hidden; }
.meter i { display: block; height: 100%; width: 0; background: var(--accent); }
.meter.hot i { background: var(--l1); }
.talk { margin: 0; padding-left: 18px; display: grid; gap: 8px; font-size: 15px; }
.note { font-size: 13px; color: var(--muted); margin: 0; }
footer { display: grid; gap: 10px; font-size: 13px; color: var(--muted); border-top: 1px solid var(--rule); padding-top: 20px; }
footer summary { cursor: pointer; min-height: 32px; color: var(--fg); }
footer ul { margin: 4px 0 0; padding-left: 18px; }
.fail { color: var(--warn); }

/* Index: a full-bleed photo with the title over it, then the route as photo cards grouped by room. */
.hero {
  position: relative; overflow: hidden; display: grid; align-content: end; background: var(--stage);
  padding: clamp(220px, 46vw, 440px) max(var(--gutter), env(safe-area-inset-right)) 8px max(var(--gutter), env(safe-area-inset-left));
}
.hero img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; object-position: 40% 55%; }
.hero::after {
  content: ""; position: absolute; inset: 0;
  background: linear-gradient(to top, var(--bg) 0%, color-mix(in srgb, var(--bg) 70%, transparent) 38%, transparent 72%);
}
.hero .copy { position: relative; z-index: 1; width: 100%; max-width: calc(var(--max) - 2 * var(--gutter)); margin: 0 auto; }
.hero h1 { font-size: clamp(38px, 6.4vw, 76px); max-width: 15ch; }
.status { font-size: 13px; color: var(--muted); margin: 16px 0 0; }
.status::before { content: ""; display: inline-block; width: 7px; height: 7px; border-radius: 50%; background: var(--edge); margin-right: 8px; vertical-align: 1px; }
.status.ready::before { background: var(--l3); }
.route { list-style: none; margin: 0; padding: 0; display: grid; gap: 64px; }
.room-head { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 4px 16px; border-top: 1px solid var(--rule); padding-top: 20px; margin-bottom: 24px; }
.room h2 { font-size: clamp(30px, 4vw, 42px); margin: 0; }
.room-head span { font-size: 12px; letter-spacing: .14em; text-transform: uppercase; color: var(--muted); }
.stops { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 300px), 1fr)); gap: 44px 24px; }
.stop a { display: grid; align-content: start; gap: 8px; height: 100%; color: var(--fg); text-decoration: none; }
.stop a:focus-visible { outline-offset: 6px; }
.stop .pic { aspect-ratio: 3 / 2; overflow: hidden; background: var(--panel); margin-bottom: 10px; }
.stop img { width: 100%; height: 100%; object-fit: cover; display: block; transition: transform .7s cubic-bezier(.2, .6, .2, 1); }
.stop small { font-size: 12px; letter-spacing: .14em; text-transform: uppercase; color: var(--muted); }
.stop b { font-family: var(--display); font-weight: 400; font-size: 25px; line-height: 1.2; }
.stop span { font-size: 15px; color: var(--muted); }
.stop .more { color: var(--fg); font-size: 14px; margin-top: 4px; }
.stop .more i { font-style: normal; display: inline-block; margin-left: 6px; transition: transform .3s; }
@media (hover: hover) {
  .stop a:hover img { transform: scale(1.04); }
  .stop a:hover .more i { transform: translateX(4px); }
}
@media (prefers-reduced-motion: reduce) { .stop img, .stop .more i { transition: none; } }

