// Screenshots of the index and one stop at phone and desktop sizes. Usage: node shots.mjs <outdir>
import { webkit, devices } from "/Users/kunabel/workspace/MercedesExperience/node_modules/@playwright/test/index.mjs";
const out = process.argv[2];
const browser = await webkit.launch();
const runs = [
  ["phone", devices["iPhone 15"], { colorScheme: "light" }],
  ["desktop", { viewport: { width: 1440, height: 900 } }, {}],
];
for (const [name, dev, extra] of runs) {
  const ctx = await browser.newContext({ ...dev, ...extra });
  const page = await ctx.newPage();
  const errors = [];
  page.on("pageerror", e => errors.push(e.message));
  page.on("console", m => { if (m.type() === "error") errors.push(m.text()); });
  await page.goto("http://localhost:8765/index.html");
  await page.waitForSelector(".stop img");
  // load every lazy image for the full-page shot
  await page.evaluate(async () => { document.querySelectorAll("img[loading=lazy]").forEach(i => (i.loading = "eager")); await Promise.all([...document.images].map(i => i.decode().catch(() => {}))); });
  await page.screenshot({ path: `${out}/index-${name}-top.png` });
  await page.evaluate(() => scrollTo(0, document.querySelector(".route").offsetTop - 20));
  await page.screenshot({ path: `${out}/index-${name}-route.png` });
  const scroll = await page.evaluate(() => [document.documentElement.scrollWidth, innerWidth]);
  await page.goto("http://localhost:8765/stop.html?s=300sl&debug");
  await page.waitForFunction(() => window.__tour?.stats.frames > 10, null, { timeout: 20000 });
  await page.screenshot({ path: `${out}/stop-${name}.png`, fullPage: name === "desktop" });
  await page.getByRole("button", { name: "Museum photo", exact: true }).click();
  await page.waitForTimeout(300);
  await page.screenshot({ path: `${out}/stop-${name}-photo.png` });
  console.log(name, "index scrollW/innerW", scroll, "errors", errors);
  await ctx.close();
}
await browser.close();

// Load a page in headless Chromium, screenshot it, and print design tokens and computed styles. Usage: node probe.mjs <url> <outdir>
import { chromium } from "/Users/kunabel/workspace/MercedesExperience/node_modules/@playwright/test/index.mjs";
const [url, out] = process.argv.slice(2);
const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, locale: "hu-HU" });
const page = await ctx.newPage();
const res = await page.goto(url, { waitUntil: "domcontentloaded", timeout: 30000 });
console.log("status", res?.status());
await page.waitForTimeout(6000);
await page.screenshot({ path: `${out}/site-top.png` });
await page.mouse.wheel(0, 1600); await page.waitForTimeout(2000);
await page.screenshot({ path: `${out}/site-scroll1.png` });
await page.mouse.wheel(0, 1600); await page.waitForTimeout(2000);
await page.screenshot({ path: `${out}/site-scroll2.png` });
const info = await page.evaluate(() => {
  const vars = {};
  for (const sheet of document.styleSheets) {
    let rules; try { rules = sheet.cssRules; } catch { continue; }
    for (const r of rules) if (r.style) for (const p of r.style) if (p.startsWith("--") && /color|font|radius|space|grey|gray|blue|black|white/i.test(p)) vars[p] ??= r.style.getPropertyValue(p).trim();
  }
  const fonts = [...document.fonts].map(f => `${f.family} ${f.weight} ${f.style}`);
  const pick = sel => [...document.querySelectorAll(sel)].filter(e => e.offsetParent && e.textContent.trim()).slice(0, 3).map(e => {
    const s = getComputedStyle(e);
    return { sel, text: e.textContent.trim().slice(0, 40), font: s.fontFamily.slice(0, 60), size: s.fontSize, weight: s.fontWeight, lh: s.lineHeight, ls: s.letterSpacing, tt: s.textTransform, color: s.color, bg: s.backgroundColor, radius: s.borderRadius, border: s.border.slice(0, 40), pad: s.padding };
  });
  const body = getComputedStyle(document.body);
  return {
    title: document.title, bodyBg: body.backgroundColor, bodyColor: body.color, bodyFont: body.fontFamily,
    fonts: [...new Set(fonts)].slice(0, 20), vars: Object.entries(vars).slice(0, 80),
    els: ["h1", "h2", "h3", "p", "a", "button", "header", "nav", "footer"].flatMap(pick),
  };
});
console.log(JSON.stringify(info, null, 1));
await browser.close();

// Measure specific design values on a page. Usage: node probe2.mjs <url> <outdir>
import { chromium, devices } from "/Users/kunabel/workspace/MercedesExperience/node_modules/@playwright/test/index.mjs";
const [url, out] = process.argv.slice(2);
const browser = await chromium.launch();
for (const [name, opts] of [["desktop", { viewport: { width: 1440, height: 900 } }], ["phone", devices["iPhone 15"]]]) {
  const page = await (await browser.newContext({ ...opts, locale: "hu-HU" })).newPage();
  await page.goto(url, { waitUntil: "domcontentloaded", timeout: 30000 });
  await page.waitForTimeout(6000);
  if (name === "phone") { await page.screenshot({ path: `${out}/phone-top.png` }); await page.mouse.wheel(0, 900); await page.waitForTimeout(1500); await page.screenshot({ path: `${out}/phone-scroll.png` }); continue; }
  const info = await page.evaluate(() => {
    const root = getComputedStyle(document.documentElement);
    const tokens = {};
    for (const n of ["--wb-border-radius-main", "--wb-color-text-primary", "--wb-color-text-secondary", "--wb-color-section-main", "--wb-color-section-fixed-black", "--wb-color-shape-brand-default", "--wb-color-shape-brand-on-contrast-default", "--wb-color-border-primary", "--wb-color-border-secondary", "--wb-link-inline-text-color-default", "--wb-color-text-on-contrast-primary", "--wb-color-ui-shape-neutral", "--wb-spacing-m", "--wb-spacing-l", "--wb-grid-gutter-width", "--wb-color-section-secondary"])
      tokens[n] = root.getPropertyValue(n).trim();
    const st = (e, extra = []) => { const s = getComputedStyle(e); const r = e.getBoundingClientRect();
      return Object.fromEntries([["tag", e.tagName + "." + [...e.classList].slice(0, 2).join(".")], ["text", e.textContent.trim().slice(0, 30)], ["w×h", `${Math.round(r.width)}×${Math.round(r.height)}`],
        ...["fontFamily", "fontSize", "fontWeight", "lineHeight", "letterSpacing", "color", "backgroundColor", "backgroundImage", "borderRadius", "border", "padding", ...extra].map(k => [k, String(s[k]).slice(0, 90)])]); };
    const vis = e => { const r = e.getBoundingClientRect(); return r.width > 0 && r.height > 0; };
    // buttons / button-like links
    const btns = [...document.querySelectorAll("a, button")].filter(e => vis(e) && /ajánlat|információ|modellek|áttekint|mentalit|GT SUV 53/i.test(e.textContent) && e.textContent.trim().length < 40).slice(0, 5).map(e => st(e));
    // rounded big boxes (cards)
    const cards = [...document.querySelectorAll("div, a, section, article, li")].filter(e => { const s = getComputedStyle(e), r = e.getBoundingClientRect(); return vis(e) && parseFloat(s.borderTopLeftRadius) > 0 && r.width > 300 && r.height > 150; }).slice(0, 4).map(e => st(e, ["overflow", "boxShadow"]));
    const header = document.querySelector("header") ?? document.querySelector("[class*=header]");
    const ps = [...document.querySelectorAll("p")].filter(vis).slice(0, 4).map(e => st(e));
    const h3 = [...document.querySelectorAll("h3, h4")].filter(vis).slice(0, 3).map(e => st(e));
    const sections = [...document.querySelectorAll("main > *, main section")].filter(vis).slice(0, 8).map(e => ({ tag: e.tagName + "." + [...e.classList].slice(0, 2).join("."), bg: getComputedStyle(e).backgroundColor, h: Math.round(e.getBoundingClientRect().height) }));
    const navlinks = [...document.querySelectorAll("header a, header button, nav a")].filter(vis).slice(0, 2).map(e => st(e));
    // gradient overlays inside cards
    const grads = [...document.querySelectorAll("*")].filter(e => vis(e) && getComputedStyle(e).backgroundImage.includes("gradient")).slice(0, 4).map(e => ({ tag: e.tagName + "." + [...e.classList].slice(0, 2).join("."), g: getComputedStyle(e).backgroundImage.slice(0, 160) }));
    return { tokens, header: header && st(header), navlinks, btns, cards, ps, h3, sections, grads };
  });
  console.log(JSON.stringify(info, null, 1));
}
await browser.close();

