/* Layout shared by the index and every stop, after the current mercedes-benz.com pages: black header bar and hero, white
   page, condensed serif headlines, black photo cards with 12 px corners, pill buttons. Light by default, dark on request.
   Colours are tokens and the 3-D scene reads them too; --band and --card are the fixed-black areas. */
@font-face {   /* Instrument Serif (SIL OFL 1.1, fonts/OFL.txt), standing in for the brand's proprietary condensed serif */
  font-family: "Instrument Serif"; font-weight: 400; font-style: normal; font-display: swap;
  src: url("fonts/instrument-serif-latin-400.woff2") format("woff2");
}
:root {
  --bg: #ffffff; --panel: #f4f4f4; --fg: #333333; --muted: #696969; --rule: #e8e8e8; --edge: #9f9f9f;
  --accent: #0078d6; --stage: #ececec;
  --band: #000000; --band-fg: #ffffff; --band-muted: #bbbbbb; --band-edge: #696969; --card: #000000;
  --l1: #d9480f; --l2: #e8a317; --l3: #2b8a3e; --l4: #1c64c4; --l5: #8e44ad;
  --metal: #8a96a1; --warn: #c92a2a;
  --display: "Instrument Serif", ui-serif, Georgia, "Times New Roman", serif;
  --body: -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --gutter: clamp(16px, 4vw, 40px); --max: 1440px; --radius: 12px;
  color-scheme: light;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --bg: #000000; --panel: #161616; --fg: #ffffff; --muted: #a3a3a3; --rule: #333333; --edge: #696969;
    --accent: #008dfc; --stage: #111111; --card: #161616;
    --l1: #ff7a45; --l2: #f5c242; --l3: #5cc46f; --l4: #5b9bf0; --l5: #b77fd6; --metal: #6f7c87; --warn: #ff6b6b;
    color-scheme: dark;
  }
}
:root[data-theme="dark"] {
  --bg: #000000; --panel: #161616; --fg: #ffffff; --muted: #a3a3a3; --rule: #333333; --edge: #696969;
  --accent: #008dfc; --stage: #111111; --card: #161616;
  --l1: #ff7a45; --l2: #f5c242; --l3: #5cc46f; --l4: #5b9bf0; --l5: #b77fd6; --metal: #6f7c87; --warn: #ff6b6b;
  color-scheme: dark;
}
[hidden] { display: none !important; }
* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body { margin: 0; background: var(--bg); color: var(--fg); font-family: var(--body); font-size: 16px; line-height: 1.55; letter-spacing: .2px; -webkit-font-smoothing: antialiased; }
a { color: inherit; text-decoration-color: var(--edge); text-underline-offset: 3px; }
.wrap {
  max-width: var(--max); margin: 0 auto; display: grid; gap: 32px;
  padding: 40px max(var(--gutter), env(safe-area-inset-right)) max(56px, env(safe-area-inset-bottom)) max(var(--gutter), env(safe-area-inset-left));
}
